@patch
def stationary_model(
    self:LGSSystem, 
    vg:int|Iterable|VelocityGroups=6, # Specification of velocity groups 
    # output='total_flux' # Operator to be applied to solution to obtain the output
    solver:Solver|dict|None=None,
) -> StationaryModel: # Model for the steady-state LGS system
    """Return a pyMOR `StationaryModel` for the steady state cw LGS system."""
    vg = VelocityGroups(vg)
    if solver is None: solver = {}
    if isinstance(solver, dict):
        default_preconditioner = dict(spilu_drop_tol=1e-3, spilu_fill_factor=20, spilu_permc_spec='COLAMD')
        preconditioner = BlockSpILUPreconditioner(-self._reaction(vg), self.Flux.source.size, **(default_preconditioner | solver.get('preconditioner', {})))
        default_solver = dict(rtol=1e-2, atol=0)
        solver = ScipyGCROTMKSolver(**(default_solver | solver | {'preconditioner': preconditioner}))
    return StationaryModel(
        self.operator(vg).with_(solver=solver),
        self.rhs(vg), 
        products=self._products(vg),
        data={
            'velocity_groups': vg,
            'grid': OnedUnstructuredGrid(vg.edges)
        }
    )

# %% ../nbs/api/lgssystem.ipynb #ab273296
def _refined_vg_edges(flux:DataArray, rtol:float=1e-2, atol=0, fraction:float=0.15):
    coarse_int = xsi.cumulative_trapezoid(flux, 'v')
    fine_int = xsi.cumulative_simpson(flux, 'v')
    dims = [d for d in flux.dims if d != 'v']
    int_err = abs((fine_int - coarse_int).diff('v'))/(fine_int.isel(v=-1) + atol)
    int_err = int_err.max(dims)
    global_err = int_err.sum('v')
    logger.info(f"Model with {len(flux.v)} velocity groups has fractional error {global_err.item():.2e}")
    if global_err.item() < rtol: return [], coarse_int.isel(v=-1), fine_int.isel(v=-1), global_err
    num_to_refine = max(1, int(len(int_err.v) * fraction))
    new_edges = int_err.sortby(int_err, ascending=False)[:num_to_refine].v
    return new_edges, coarse_int.isel(v=-1), fine_int.isel(v=-1), global_err

# %% ../nbs/api/lgssystem.ipynb #b524155e
@patch
def interp_like(self:XarrayVectorArray, other:XarrayVectorArray | XarrayVectorSpace):
    if isinstance(other, XarrayVectorArray):
        target_space = other.space
    else:
        target_space = other
    array = self.array.interp_like(target_space._array).fillna(0)
    return target_space.make_array(array)

# %% ../nbs/api/lgssystem.ipynb #411acad2
def refine_solution(old_sol, old_model, new_model):
    """Refine the solution from an old model to a new model by interpolating the normalized solution onto the new model's velocity grid."""
    old_sol_norm = old_sol.array.transpose(..., 'Atomic velocity')/old_model.data['velocity_groups']['VGWidth']
    new_sol_norm = old_sol_norm.interp_like(new_model.operator.source._array).fillna(0)
    new_sol = new_sol_norm * new_model.data['velocity_groups']['VGWidth']
    return new_model.operator.source.make_array(new_sol)

# %% ../nbs/api/lgssystem.ipynb #db297031
def transfer_ilu(old_model, new_model):
    old_centers = old_model.data['velocity_groups']['VGCenter']
    new_centers = new_model.data['velocity_groups']['VGCenter']
    old_ilu = old_model.operator.solver.preconditioner._ilu
    n_groups = len(old_ilu) // len(old_centers)
    for j in list(range(n_groups))[::-1]:
        for i in list(range(len(old_centers)))[::-1]:
            if old_centers[i] not in new_centers:
                old_ilu[i + j * len(old_centers)] = None
                old_ilu.insert(i + j * len(old_centers), None)
    new_model.operator.solver.preconditioner._ilu = old_ilu

# %% ../nbs/api/lgssystem.ipynb #e8ace62f
def create_adaptive_model(model_func, solve_func, flux_func, vg, rtol, atol=0, refine_fraction=0.2, max_iterations=50, max_velocity_groups=500, use_initial_guess=True, reuse_ilu=True, return_intermediate=False):
    model = model_func(vg=vg)
    sol = solve_func(model, initial_guess=None)
    flux = flux_func(model, sol)
    intermediate_results = []
    for iteration in range(max_iterations):
        logger.info(f"Starting refinement iteration {iteration + 1} -----------------------")
        iteration_tick = clock()
        new_edges, *intermediate = _refined_vg_edges(flux, rtol=rtol, atol=atol, fraction=refine_fraction)
        intermediate_results.append(intermediate)
        if len(new_edges) == 0: 
            logger.info(f"Stopping refinement because global error is below the tolerance.")
            break
        vg = VelocityGroups(np.union1d(model.data['velocity_groups'].edges, new_edges))
        if len(vg.edges) > max_velocity_groups:
            logger.info(f"Stopping refinement because the number of velocity groups exceeded the maximum allowed ({max_velocity_groups}).")
            break
        tick = clock()
        new_model = model_func(vg=vg)
        logger.info(f"Created new model with {vg['VGNumber']} velocity groups in {clock() - tick:.2f} seconds")
        initial_guess = refine_solution(sol, model, new_model) if use_initial_guess else None
        if reuse_ilu: transfer_ilu(model, new_model)
        tick = clock()
        model = new_model
        sol = solve_func(model, initial_guess=initial_guess)
        flux = flux_func(model, sol)
        logger.info(f"Solve time for iteration {iteration + 1}: {clock() - tick:.2f} seconds")
        logger.info(f"Total time for iteration {iteration + 1}: {clock() - iteration_tick:.2f} seconds")
    else:
        logger.info(f"Stopping refinement after reaching the maximum number of iterations.")
    if return_intermediate:
        coarse_int, fine_int, global_err = unzip(intermediate_results)
        global_err = xr.concat(global_err, dim='iteration')
        coarse_int = xr.concat(coarse_int, dim='iteration')
        fine_int = xr.concat(fine_int, dim='iteration')
        intermediate_results = Dataset({'coarse_int': coarse_int, 'fine_int': fine_int, 'global_err': global_err})
        return model, sol, intermediate_results
    return model, sol    

# %% ../nbs/api/lgssystem.ipynb #24f80def
@patch
def adaptive_stationary_model(
    self:LGSSystem, 
    mu, # Parameter values to use during velocity-group refinement
    vg=20, # Initial velocity groups
    solver=None, # Solver to use for the linear system
    rtol=.02, # Global error tolerance for the return flux integral
    atol=0, # Absolute tolerance for the return flux integral  
    refine_fraction=0.2, # Fraction of velocity groups to refine at each iteration
    return_intermediate=False, # Whether to return intermediate integration results
    max_iterations=50, # Maximum number of refinement iterations
    max_velocity_groups=500, # Maximum number of velocity groups allowed during refinement
    use_initial_guess=True, # Whether to use the initial guess when solving the refined model
    reuse_ilu=True, # Whether to reuse the ILU factorization from the previous model
)->StationaryModel: # Steady-state LGS model with more velocity groups in regions that produce more return flux
    """Create a `StationaryModel` with narrower velocity bins in velocity regions with higher flux."""
    outer_tick = clock()
    model_func = lambda vg: self.stationary_model(vg=vg, solver=solver)
    solve_func = lambda model, initial_guess=None: model.operator.apply_inverse(model.rhs.as_range_array(), model.parameters.parse(mu), initial_guess=initial_guess)
    flux_func = lambda model, sol: model.flux_distribution(sol).array.rename('flux').rename({'Atomic velocity': 'v'})
    out = create_adaptive_model(
        model_func, solve_func, flux_func, vg, rtol, atol=atol, refine_fraction=refine_fraction, 
        max_iterations=max_iterations, max_velocity_groups=max_velocity_groups, use_initial_guess=use_initial_guess, 
        reuse_ilu=reuse_ilu, return_intermediate=return_intermediate
    )
    logger.info(f"============== Total refinement time: {clock() - outer_tick:.2f} seconds")
    return out

