# %% ../nbs/api/lgssystem.ipynb #6334f25e
def transpose_operator(op):
    op = expand(op)
    op = sum([c * op.operators[1] * op.operators[0] * op.operators[2] for c, op in zip(op.coefficients, op.operators)])
    return op

def transpose_vector(v):
    space = XarrayVectorSpace({k: v.space.coord_data[k] for k in ['Atomic velocity', 'Fourier coefficient', 'Density matrix']})
    return space.from_xarray(v.array)

# %% ../nbs/api/lgssystem.ipynb #9817a20e
def transpose_floq_model(floq_model):
    preconditioner_matrix = transpose_operator(floq_model.operator.solver.preconditioner.matrix)
    block_size = floq_model.operator.source.size // floq_model.data['velocity_groups']['VGNumber']
    preconditioner = floq_model.operator.solver.preconditioner.with_(matrix=preconditioner_matrix, block_size=block_size)
    solver = floq_model.operator.solver.with_(preconditioner=preconditioner)
    operator = transpose_operator(floq_model.operator).with_(solver=solver)
    rhs = transpose_vector(floq_model.rhs.as_range_array())
    return StationaryModel(operator=operator, rhs=rhs, products=floq_model.products, data=floq_model.data)

