    """Create a `StationaryModel` with narrower velocity bins in velocity regions with higher flux."""
    outer_tick = clock()
    model_func = lambda vg: self.stationary_floquet_model(mu, time, n_vector, nu=nu, n_operator=n_operator, vg=vg, solver=solver)
    flux_func = lambda model, sol: model.reconstructed_flux_distribution(sol, mu_refine).real.array.rename('flux').rename({'Atomic velocity': 'v'}) #.sum(['Time', 'Transition']).squeeze()
    solve_func = lambda model, initial_guess=None: model.operator.apply_inverse(model.rhs.as_range_array(), model.parameters.parse(mu_refine), initial_guess=initial_guess)
    out = create_adaptive_model(
        model_func, solve_func, flux_func, vg, rtol, atol=atol, refine_fraction=refine_fraction, max_iterations=max_iterations, 
        max_velocity_groups=max_velocity_groups, use_initial_guess=True, reuse_ilu=True, return_intermediate=return_intermediate
    )
    logger.info(f"============== Total refinement time: {clock() - outer_tick:.2f} seconds")
    return out
